import java.util.UUID

object Accessibility : AlloyService {

    private const val TAG = "Accessibility"
    private const val TOPIC = "com.apple.private.alloy.accessibility.local"
    override val handlesTopics = listOf(TOPIC)


    override fun acceptsMessageType(msg: AlloyMessage) = msg is DictionaryMessage
    override fun acceptsLocalDeviceRole(device: AlloyService.Device) = device == AlloyService.Device.WATCH

    override fun receiveMessage(msg: AlloyMessage, handler: AlloyHandler) {
        if(msg !is DataMessage)
            throw Exception("$TAG expects DataMessage but got $msg")

        val parsed = (BPListParser().parse(msg.payload) as BPDict).values

        if(parsed.containsKey(BPAsciiString("sendSnapshots"))) {
            Log.d(TAG, "got request for snapshots")
            WatchState.incrementProgress()
            WatchState.setPairingStage("sent text size snapshots")
            val syncHandler = AlloyController.getHandlerForChannel("UTunDelivery-Default-Sync-C")!!
            sendSnapshots(syncHandler)
        }
    }


    private fun sendSnapshots(handler: AlloyHandler) {

        val rainbow1 = "".fromHex()
        //val rainbow1 = "ca".fromHex()
        //val rainbow2 = "".fromHex()
        //val rainbow2 = "".fromHex()
        val rainbow3 = "".fromHex()
        val empty = "".fromHex()

        val encoded = BPSDict(mapOf(
            "\$objects" to BPArray(listOf(
                BPAsciiString("\$null"),
                BPSDict(mapOf(
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x08), BPUid.fromInt(0x0f), BPUid.fromInt(0x12), BPUid.fromInt(0x15), BPUid.fromInt(0x18), BPUid.fromInt(0x1b))),
                    "\$class" to BPUid.fromInt(0x1e),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x02), BPUid.fromInt(0x03), BPUid.fromInt(0x04), BPUid.fromInt(0x05), BPUid.fromInt(0x06), BPUid.fromInt(0x07)))
                )),
                BPAsciiString("UICTContentSizeCategoryS"),
                BPAsciiString("UICTContentSizeCategoryXS"),
                BPAsciiString("UICTContentSizeCategoryXL"),
                BPAsciiString("UICTContentSizeCategoryXXL"),
                BPAsciiString("UICTContentSizeCategoryXXXL"),
                BPAsciiString("UICTContentSizeCategoryL"),
                BPSDict(mapOf(
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0b), BPUid.fromInt(0x0b))), // rainbow 1
                    "\$class" to BPUid.fromInt(0x0e),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x09), BPUid.fromInt(0x0a)))
                )),
                BPFalse, // 0x09
                BPTrue, // 0x0a
                BPSDict(mapOf( // rainbow1: 0x0b
                    "NS.data" to BPData(rainbow1),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "\$classes" to BPArray(listOf(BPAsciiString("NSMutableData"), BPAsciiString("NSData"), BPAsciiString("NSObject"))),
                    "\$classname" to BPAsciiString("NSMutableData")
                )),
                BPSDict(mapOf( // rainbow2: 0x0d
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "\$classes" to BPArray(listOf(BPAsciiString("NSDictionary"), BPAsciiString("NSObject"))),
                    "\$classname" to BPAsciiString("NSDictionary")
                )),
                BPSDict(mapOf(
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0b), BPUid.fromInt(0x0b))), // rainbow 2
                    "\$class" to BPUid.fromInt(0x0e),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x09), BPUid.fromInt(0x0a)))
                )),
                BPSDict(mapOf( // rainbow3: 0x10
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0b), BPUid.fromInt(0x0b))), // rainbow 3
                    "\$class" to BPUid.fromInt(0x0e),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x09), BPUid.fromInt(0x0a)))
                )),
                BPSDict(mapOf(
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0b), BPUid.fromInt(0x0b))), // rainbow 1
                    "\$class" to BPUid.fromInt(0x0e),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x09), BPUid.fromInt(0x0a)))
                )),
                BPSDict(mapOf(
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0b), BPUid.fromInt(0x0b))), // rainbow 2
                    "\$class" to BPUid.fromInt(0x0e),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x09), BPUid.fromInt(0x0a)))
                )),
                BPSDict(mapOf(
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0b), BPUid.fromInt(0x0b))), // rainbow 3
                    "\$class" to BPUid.fromInt(0x0e),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x09), BPUid.fromInt(0x0a)))
                )),
                BPSDict(mapOf(
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x0c)
                )),
                BPSDict(mapOf(
                    "\$classes" to BPArray(listOf(BPAsciiString("NSMutableDictionary"), BPAsciiString("NSDictionary"), BPAsciiString("NSObject"))),
                    "\$classname" to BPAsciiString("NSMutableDictionary")
                ))
            )),
            "\$version" to BPInt(100000),
            "\$archiver" to BPAsciiString("NSKeyedArchiver"),
            "\$top" to BPSDict(mapOf("root" to BPUid.fromInt(1)))
        ))

        val encodedSmall = BPSDict(mapOf(
            "\$objects" to BPArray(listOf(
                BPAsciiString("\$null"), // 0x00
                BPSDict(mapOf( // 0x01
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0b), BPUid.fromInt(0x0a), BPUid.fromInt(0x0b), BPUid.fromInt(0x0a), BPUid.fromInt(0x0b), BPUid.fromInt(0x0a))),
                    "\$class" to BPUid.fromInt(0x11),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x02), BPUid.fromInt(0x03), BPUid.fromInt(0x04), BPUid.fromInt(0x05), BPUid.fromInt(0x06), BPUid.fromInt(0x07)))
                )),
                BPAsciiString("UICTContentSizeCategoryS"), // 0x02
                BPAsciiString("UICTContentSizeCategoryXS"), // 0x03
                BPAsciiString("UICTContentSizeCategoryXL"), // 0x04
                BPAsciiString("UICTContentSizeCategoryXXL"), // 0x05
                BPAsciiString("UICTContentSizeCategoryXXXL"), // 0x06
                BPAsciiString("UICTContentSizeCategoryL"), // 0x07
                BPFalse, // 0x08
                BPTrue, // 0x09
                BPSDict(mapOf( // 0x0a
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0d), BPUid.fromInt(0x0d))), // rainbow 1
                    "\$class" to BPUid.fromInt(0x11),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x08), BPUid.fromInt(0x09)))
                )),
                BPSDict(mapOf( // 0x0b
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0e), BPUid.fromInt(0x0d))), // rainbow 3
                    "\$class" to BPUid.fromInt(0x11),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x08), BPUid.fromInt(0x09)))
                )),
                BPSDict(mapOf( // 0x0c
                    "NS.objects" to BPArray(listOf(BPUid.fromInt(0x0f), BPUid.fromInt(0x0d))), // rainbow 3
                    "\$class" to BPUid.fromInt(0x11),
                    "NS.keys" to BPArray(listOf(BPUid.fromInt(0x08), BPUid.fromInt(0x09)))
                )),
                BPSDict(mapOf( // rainbow1: 0x0d
                    "NS.data" to BPData(rainbow1),
                    "\$class" to BPUid.fromInt(0x10)
                )),
                BPSDict(mapOf( // rainbow2: 0x0e
                    "NS.data" to BPData("00".fromHex()),
                    "\$class" to BPUid.fromInt(0x10)
                )),
                BPSDict(mapOf( // rainbow3: 0x0f
                    "NS.data" to BPData(empty),
                    "\$class" to BPUid.fromInt(0x10)
                )),
                BPSDict(mapOf( // mutable data: 0x10
                    "\$classes" to BPArray(listOf(BPAsciiString("NSMutableData"), BPAsciiString("NSData"), BPAsciiString("NSObject"))),
                    "\$classname" to BPAsciiString("NSMutableData")
                )),
                BPSDict(mapOf( // dict: 0x11
                    "\$classes" to BPArray(listOf(BPAsciiString("NSDictionary"), BPAsciiString("NSObject"))),
                    "\$classname" to BPAsciiString("NSDictionary")
                )),
            )),
            "\$version" to BPInt(100000),
            "\$archiver" to BPAsciiString("NSKeyedArchiver"),
            "\$top" to BPSDict(mapOf("root" to BPUid.fromInt(1)))
        ))

        //println(encodedSmall.renderAsTopLevelObject().hex())
        handler.sendData(encodedSmall.renderAsTopLevelObject(), TOPIC, UUID.randomUUID(), compress = true)
    }
}